import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import { kbdClassNameBySize, kbdGroupClassName } from "./view";
import type { KbdSize } from "./view";

export type { KbdSize };

export {
  kbdBaseClassName,
  kbdClassNameBySize,
  kbdGroupClassName,
} from "./view";

export type ViewConfig = Readonly<{
  label: string;
  size?: KbdSize;
  className?: string;
}>;

export const view = <ParentMessage>({
  label,
  size = "Default",
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();
  const classNames = [kbdClassNameBySize(size), className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.kbd([h.Class(classNames)], [label]);
};

export const groupView = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();
  const classNames = [kbdGroupClassName, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

  return h.span([h.Class(classNames)], children);
};

export type KbdSize = "Small" | "Default";

export const kbdBaseClassName =
  "inline-flex min-w-6 items-center justify-center rounded-md border border-gray-300 bg-gray-50 px-1.5 font-mono font-medium text-gray-900 shadow-sm";

export const kbdGroupClassName = "inline-flex items-center gap-1";

export const kbdClassNameBySize = (size: KbdSize = "Default"): string =>
  size === "Small"
    ? `${kbdBaseClassName} h-6 text-xs`
    : `${kbdBaseClassName} h-7 text-sm`;

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Kbd from "./index";

const view = (): Html => {
  const h = html<never>();

  return Kbd.groupView([
    Kbd.view({ label: "Cmd" }),
    h.span([], ["+"]),
    Kbd.view({ label: "K" }),
  ]);
};

describe("Kbd registry view", () => {
  test("renders the documented static surface", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Cmd")).toExist(),
      Scene.expect(Scene.text("K")).toExist()
    );
  });
});
